  d_permis: { id: 'd_permis', ico: '📲', n: 'Guardià/ana dels permisos|Guardián/a de los permisos', d: "Decideixes quins permisos tenen sentit, tries l'opció més petita i saps treure'ls.|Decides qué permisos tienen sentido, eliges la opción más pequeña y sabes quitarlos." },
  d_disp: { id: 'd_disp', ico: '🛡️', n: 'Dispositiu blindat|Dispositivo blindado', d: "Coneixes els escuts dels dispositius: wifi amb cap, actualitzacions, còpies i bloqueig.|Conoces los escudos de los dispositivos: wifi con cabeza, actualizaciones, copias y bloqueo." },
