  d_compra: { id: 'd_compra', ico: '🪙', n: 'Comprador/a amb cap|Comprador/a con cabeza', d: "Saps com guanyen diners els videojocs «gratis», passes les monedes a euros i compres amb un adult.|Sabes cómo ganan dinero los videojuegos «gratis», pasas las monedas a euros y compras con un adulto." },
  d_algo: { id: 'd_algo', ico: '🧭', n: "Pilot/a de l'algoritme|Piloto del algoritmo", d: "Entens per què veus el que veus, surts de la bombolla i decideixes quan parar.|Entiendes por qué ves lo que ves, sales de la burbuja y decides cuándo parar." },
  d_honest: { id: 'd_honest', ico: '🏆', n: 'Consumidor/a digital · curs complet|Consumidor/a digital · curso completo', d: "Projecte acabat: has fet un anunci honest i has completat les sis unitats de Tech Digital.|Proyecto terminado: has hecho un anuncio honesto y has completado las seis unidades de Tech Digital." }
